131	    /** Open a claim's editor: the claim is locked for every other user until the user saves or cancels it,
132	     *  or the sheet's today changes. Refused for a claim that is not a DRAFT, a claim in a closed period, and
133	     *  a claim another user has locked; a refused open takes no lock. */
134	    @Transactional
135	    public Claim lock(String sheetId, String user, long claimId) {
136	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
137	        if (claim.getStatus() != ClaimStatus.DRAFT) {
138	            throw new ClaimNotDraftException(claim.getStatus());
139	        }
140	        refuseClosed(sheetId, claim.getDate());
141	        refuseLocked(claim, user);
142	        claim.setLockedBy(user);
143	        return claims.saveAndFlush(claim);
144	    }
