146	    /** Close a claim's editor (cancel): the user's lock on it is released; another user's stays. */
147	    @Transactional
148	    public Claim unlock(String sheetId, String user, long claimId) {
149	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
150	        if (user.equals(claim.getLockedBy())) {
151	            claim.setLockedBy(null);
