157	    /** Move a claim to another status; refused when the user's role may not open, settle or void it (the
158	     *  sheet's permission matrix), when its current status does not allow it,
159	     *  or when the user settling it is the one who opened it. A clerk settling a claim whose due is above
160	     *  the sheet's clerk limit (a due of n/a is within any limit) puts it PENDING instead, for a steward to
161	     *  approve or reject; its due stays live. Settling fixes the
162	     *  claim's due at its grade's rate in force on its date (a claim bound by a statement at the figure it
163	     *  bound), its late charge on the sheet's today frozen in on top; with no figure then, its due stays live. */
164	    @Transactional
165	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
166	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
167	        refuseClosed(sheetId, claim.getDate());
168	        roles.require(sheetId, user, switch (to) {
169	            case OPEN -> "open";
170	            case SETTLED, PENDING -> "settle";
171	            case VOID -> "void";
172	            case DRAFT -> throw new IllegalStateException();
173	        });
174	        if (!claim.getStatus().canBecome(to)) {
175	            throw new ClaimStatusException(claim.getStatus(), to);
176	        }
177	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
178	            refuseVoidSettled(claim, sheetId, user);
179	        }
180	        String reversed = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED
181	                ? " reversed=" + show(claim.getSettledDue()) : "";
182	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
183	            throw new ClaimSettlerException();
184	        }
185	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
186	            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
187	        }
188	        Rollup.Snapshot before = rollup.take(sheetId);
189	        String number = claim.getNumber();
190	        if (to == ClaimStatus.OPEN) {
191	            number = sheets.nextClaimNumber(sheetId, claim.getDate());
192	            claim.setOpenedBy(user);
193	        }
194	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
195	                .orElseThrow(PersonNotFoundException::new);
196	        if (to == ClaimStatus.SETTLED) {
197	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
198	            BigDecimal due = figure == null ? null : charged(claim, figure);
199	            refuseUnproved(claim, due);
200	            if (overLimit(sheetId, user, due)) {
201	                to = ClaimStatus.PENDING;
202	            } else {
203	                claim.setSettledDue(due);
204	            }
205	        }
206	        claim.setStatus(to);
207	        claim.setNumber(number);
208	        logStatus(claim, person, user);
209	        Claim updated = claims.saveAndFlush(claim);
210	        String event = switch (to) {
211	            case OPEN -> "CLAIM_OPENED";
212	            case PENDING -> "CLAIM_PENDING";
213	            case SETTLED -> "CLAIM_SETTLED";
214	            case VOID -> "CLAIM_VOIDED";
215	            case DRAFT -> throw new IllegalStateException();
216	        };
217	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : reversed);
218	        if (to == ClaimStatus.SETTLED) {
219	            notifyWatchers(updated, person, user);
220	        }
221	        rollup.recordChanges(sheetId, user, before);
222	        return updated;
223	    }
