225	    /** Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure now, its late charge on
226	     *  the sheet's today frozen in on top (with no figure then, its due stays live). Refused unless the
227	     *  claim is PENDING and the user is a steward other than the one who opened it. */
228	    @Transactional
229	    public Claim approve(String sheetId, String user, long claimId) {
230	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
231	        refuseClosed(sheetId, claim.getDate());
232	        if (claim.getStatus() != ClaimStatus.PENDING) {
233	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
234	        }
235	        if (!roles.isSteward(sheetId, user)) {
236	            throw new ClaimApprovalException("Only a steward can approve a claim.");
237	        }
238	        if (user.equals(claim.getOpenedBy())) {
239	            throw new ClaimApprovalException("The user who opened a claim cannot approve it.");
240	        }
241	        Rollup.Snapshot before = rollup.take(sheetId);
242	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
243	                .orElseThrow(PersonNotFoundException::new);
244	        BigDecimal figure = liveDue(claim, person);
245	        BigDecimal due = figure == null ? null : charged(claim, figure);
246	        refuseUnproved(claim, due);
247	        claim.setSettledDue(due);
248	        claim.setStatus(ClaimStatus.SETTLED);
249	        logStatus(claim, person, user);
250	        Claim updated = claims.saveAndFlush(claim);
251	        audit("CLAIM_APPROVED", updated, person, user, updated.getNumber(), dueField(updated));
252	        notifyWatchers(updated, person, user);
253	        rollup.recordChanges(sheetId, user, before);
254	        return updated;
255	    }
