274	    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
275	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
276	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
277	    @Transactional
278	    public Claim resettle(String sheetId, String user, long claimId) {
279	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
280	        refuseClosed(sheetId, claim.getDate());
281	        if (!roles.isSteward(sheetId, user)) {
282	            throw new ClaimResettleException("Only a steward can re-settle a claim.");
283	        }
284	        if (claim.getStatus() != ClaimStatus.SETTLED) {
285	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
286	        }
287	        Rollup.Snapshot before = rollup.take(sheetId);
288	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
289	                .orElseThrow(PersonNotFoundException::new);
290	        BigDecimal old = claim.getSettledDue();
291	        BigDecimal figure = liveDue(claim, person);
292	        BigDecimal due = null;
293	        if (figure != null) {
294	            Sheet sheet = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
295	            due = claim.isCorrection() ? figure
296	                    : sheet.floored(figure.add(sheet.lateCharge(figure, claim.getDueBy(), claim.getDate())),
297	                            claim.getDate());
298	        }
299	        claim.setSettledDue(due);
300	        logStatus(claim, person, user);
301	        Claim updated = claims.saveAndFlush(claim);
302	        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
303	                " old=" + show(old) + " new=" + show(due));
304	        notifyWatchers(updated, person, user);
305	        rollup.recordChanges(sheetId, user, before);
306	        return updated;
307	    }
