309	    /** Reject a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last
310	     *  statement if that statement included it. Refused unless the claim is PENDING, the user is a
311	     *  steward and a reason is given. */
312	    @Transactional
313	    public Claim reject(String sheetId, String user, long claimId, String reason) {
314	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
315	        refuseClosed(sheetId, claim.getDate());
316	        if (claim.getStatus() != ClaimStatus.PENDING) {
317	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.OPEN);
318	        }
319	        if (!roles.isSteward(sheetId, user)) {
320	            throw new ClaimApprovalException("Only a steward can reject a claim.");
321	        }
322	        if (reason.isEmpty()) {
323	            throw new ClaimApprovalException("Give a reason to reject the claim.");
324	        }
325	        Rollup.Snapshot before = rollup.take(sheetId);
326	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
327	                .orElseThrow(PersonNotFoundException::new);
328	        claim.setStatus(ClaimStatus.OPEN);
329	        logStatus(claim, person, user);
330	        Claim updated = claims.saveAndFlush(claim);
331	        audit("CLAIM_REJECTED", updated, person, user, updated.getNumber(), " reason=" + reason);
332	        rollup.recordChanges(sheetId, user, before);
333	        return updated;
334	    }
