336	    /** Defer an OPEN claim to a date after the sheet's today: until the sheet's today reaches it, the claim
337	     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for
338	     *  a claim that is not OPEN, a date not after the sheet's today, and a claim in a closed period. */
339	    @Transactional
340	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
341	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
342	        refuseClosed(sheetId, claim.getDate());
343	        if (claim.getStatus() != ClaimStatus.OPEN) {
344	            throw new ClaimDeferException("Only an OPEN claim can be deferred.");
345	        }
346	        if (until == null || !until.isAfter(sheets.today(sheetId))) {
347	            throw new ClaimDeferException("Defer the claim to a date after the sheet's today.");
348	        }
349	        Rollup.Snapshot before = rollup.take(sheetId);
350	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
351	                .orElseThrow(PersonNotFoundException::new);
352	        claim.setDeferredUntil(until);
353	        Claim updated = claims.saveAndFlush(claim);
354	        audit("CLAIM_DEFERRED", updated, person, user, updated.getNumber(), " until=" + until);
355	        rollup.recordChanges(sheetId, user, before);
356	        return updated;
357	    }
