359	    /** Re-date an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement bound
360	     *  it to stays bound; its period follows the new date, and while the sheet numbers by period a move
361	     *  into another period gives it the next number of that period's sequence. A missing date is the
362	     *  sheet's today. Refused unless the user is a steward, and for a claim in any other status, a claim
363	     *  in a closed period or a new date inside one, and a date after its person's retirement. */
364	    @Transactional
365	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
366	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
367	        LocalDate on = date != null ? date : sheets.today(sheetId);
368	        refuseClosed(sheetId, claim.getDate());
369	        if (!roles.isSteward(sheetId, user)) {
370	            throw new ClaimRedateException("Only a steward can re-date a claim.");
371	        }
372	        if (!claim.getStatus().isOpen()) {
373	            throw new ClaimRedateException("Only an OPEN or PENDING claim can be re-dated.");
374	        }
375	        refuseClosed(sheetId, on);
376	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
377	                .orElseThrow(PersonNotFoundException::new);
378	        refuseRetired(person, on);
379	        Rollup.Snapshot before = rollup.take(sheetId);
380	        LocalDate old = claim.getDate();
381	        claim.setNumber(sheets.redatedClaimNumber(sheetId, claim.getNumber(), old, on));
382	        claim.setDate(on);
383	        Claim updated = claims.saveAndFlush(claim);
384	        audit("CLAIM_REDATED", updated, person, user, updated.getNumber(), " old=" + old + " new=" + on);
385	        rollup.recordChanges(sheetId, user, before);
386	        return updated;
387	    }
