389	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
390	     *  loses any figure a statement bound it to (live again until its new person's next statement), and is
391	     *  listed as its new person's newest claim. Refused unless the user's role may reassign, and for a settled or
392	     *  voided claim, a claim in a closed period, the claim's own person, or a person retired on its date. */
393	    @Transactional
394	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
395	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
396	        refuseClosed(sheetId, claim.getDate());
397	        if (!roles.allows(sheetId, user, "reassign")) {
398	            throw new ClaimReassignException("Your role may not reassign a claim.");
399	        }
400	        if (!claim.getStatus().canMove()) {
401	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
402	        }
403	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
404	                .orElseThrow(PersonNotFoundException::new);
405	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
406	        if (from.getId().equals(to.getId())) {
407	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
408	        }
409	        refuseRetired(to, claim.getDate());
410	        Rollup.Snapshot before = rollup.take(sheetId);
411	        claim.setPersonId(to.getId());
412	        claim.setStated(false, null);
413	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
414	        Claim updated = claims.saveAndFlush(claim);
415	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
416	                " from=" + from.getName() + " to=" + to.getName());
417	        rollup.recordChanges(sheetId, user, before);
418	        return updated;
419	    }
