421	    /** What a split did: the claim it kept, with the rest of its amount, and the claim it split off. */
422	    public record Split(Claim kept, Claim split) {
423	    }
424	
425	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any figure a
426	     *  statement bound it to; a new OPEN claim of the person with the amount split off, the same date and
427	     *  note, the next number, opened by the user and due by its date plus the terms in force on it, is
428	     *  listed as the sheet's newest, naming the original's number as split from. Refused unless the user's
429	     *  role may open a claim, the claim is OPEN and not deferred, and the amount is above 0.00 and below the
430	     *  claim's; and for a claim in a closed period. */
431	    @Transactional
432	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
433	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
434	        refuseClosed(sheetId, claim.getDate());
435	        roles.require(sheetId, user, "open");
436	        if (claim.getStatus() != ClaimStatus.OPEN) {
437	            throw new ClaimSplitException("Only an OPEN claim can be split.");
438	        }
439	        LocalDate today = sheets.today(sheetId);
440	        if (claim.deferredOn(today)) {
441	            throw new ClaimSplitException("The claim is deferred until " + claim.getDeferredUntil() + ".");
442	        }
443	        BigDecimal part = amount.setScale(2);
444	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
445	            throw new ClaimSplitException("Split off more than 0.00 and less than the claim's amount.");
446	        }
447	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
448	                .orElseThrow(PersonNotFoundException::new);
449	        Rollup.Snapshot before = rollup.take(sheetId);
450	        claim.setAmount(claim.getAmount().subtract(part));
451	        claim.setStated(false, null);
452	        Claim kept = claims.saveAndFlush(claim);
453	        int terms = person.getTerms() != null ? person.getTerms()
454	                : sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
455	                        .termsFor(person.gradeOn(claim.getDate()), claim.getDate());
456	        Claim split = new Claim(sheetId, person.getId(), part, claim.getDate(), claim.getDate().plusDays(terms),
457	                claim.getNote(), null);
458	        split.setListOrder(claims.maxListOrder(sheetId) + 1);
459	        split.setStatus(ClaimStatus.OPEN);
460	        split.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
461	        split.setOpenedBy(user);
462	        split.setSplitFrom(claim.getNumber());
463	        logStatus(split, person, user);
464	        split = claims.saveAndFlush(split);
465	        audit("CLAIM_SPLIT", kept, person, user, kept.getNumber(), " into=" + split.getNumber());
466	        audit("CLAIM_OPENED", split, person, user);
467	        rollup.recordChanges(sheetId, user, before);
468	        return new Split(kept, split);
469	    }
