475	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
476	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
477	     *  refused, as is one not on the sheet. */
478	    @Transactional
479	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
480	        Set<Long> chosen = new HashSet<>(claimIds);
481	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
482	            return new BulkOpened(0, chosen.size(), List.of());
483	        }
484	        List<Claim> opened = new ArrayList<>();
485	        for (Claim claim : inListOrder(sheetId, chosen)) {
486	            try {
487	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
488	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
489	                    | ActionNotAllowedException e) {
490	                // refused: left as it is
491	            }
492	        }
493	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
494	    }
