500	    /** Settle the chosen claims together in list order (people in the order they were added, each person's
501	     *  claims newest first), each as a single settle by the user would: one a clerk puts PENDING counts as
502	     *  settled, and one that cannot be settled is left as it is and counted as refused, as is one not on
503	     *  the sheet. */
504	    @Transactional
505	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
506	        Set<Long> chosen = new HashSet<>(claimIds);
507	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
508	            return new BulkSettled(0, chosen.size(), List.of());
509	        }
510	        List<Claim> settled = new ArrayList<>();
511	        for (Claim claim : inListOrder(sheetId, chosen)) {
512	            try {
513	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
514	            } catch (ClaimStatusException | ClaimSettlerException | ClaimDeferException | ClaimProofException
515	                    | PeriodClosedException | ActionNotAllowedException
516	                    | ClaimNotFoundException e) {
517	                // refused: left as it is
518	            }
519	        }
520	        return new BulkSettled(settled.size(), chosen.size() - settled.size(), settled);
521	    }
