523	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
524	     *  newest first. */
525	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
526	        Map<Long, Integer> personOrder = new HashMap<>();
527	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
528	            personOrder.put(person.getId(), personOrder.size());
529	        }
530	        return claims.findBySheetIdOrderByListOrderDesc(sheetId).stream()
531	                .filter(c -> chosen.contains(c.getId()))
532	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
533	                .toList();
534	    }
