536	    /** A person, their statements in the order taken, and their claims newest first. */
537	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
538	    }
539	
540	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
541	     *  count, and bind each claim that counts to its rate figure now, under its late charge and floor (the charge is
542	     *  never bound: it keeps following the sheet's today, and the floor is applied on top; a PENDING claim is bound only once it is back to
543	     *  OPEN); a claim that does not count, is OPEN or PENDING and dated within one of its person's holds (or its person's retirement date is reached), or is
544	     *  deferred past the sheet's today, is left unbound. */
545	    @Transactional
546	    public Stated statement(String sheetId, String user, long personId) {
547	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
548	        LocalDate today = sheets.today(sheetId);
549	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
550	        Rollup.Snapshot before = rollup.take(sheetId);
551	        BigDecimal total = BigDecimal.ZERO.setScale(2);
552	        boolean figure = false;
553	        int counted = 0;
554	        for (Claim claim : theirs) {
555	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && (person.heldOn(claim.getDate()) || person.retiredBy(today)))
556	                    || claim.deferredOn(today)) {
557	                claim.setStated(false, null);
558	                continue;
559	            }
560	            BigDecimal due = due(claim, person);
561	            if (due != null) {
562	                total = total.add(charged(claim, due));
563	                figure = true;
564	            }
565	            claim.setStated(true, due);
566	            counted++;
567	        }
568	        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
569	        BigDecimal summed = total;
570	        BigDecimal dueTotal = rated || figure
571	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
572	        claims.saveAllAndFlush(theirs);
573	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
574	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
575	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
576	        rollup.recordChanges(sheetId, user, before);
577	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
578	    }
579	
580	    /** Cancel a person's last statement: the claims it bound are live again (a figure an earlier statement
581	     *  bound is not restored), and the statement before it becomes their last. Refused unless the user is a
582	     *  steward and the person has a statement. */
583	    @Transactional
584	    public Stated cancelStatement(String sheetId, String user, long personId) {
585	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
586	        if (!roles.isSteward(sheetId, user)) {
587	            throw new StatementCancelException("Only a steward can cancel a statement.");
588	        }
589	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
590	        List<Statement> taken = statements.findByPersonIdOrderByIdAsc(personId);
591	        if (taken.isEmpty()) {
592	            throw new StatementCancelException(person.getName() + " has no statement to cancel.");
593	        }
594	        Statement last = taken.get(taken.size() - 1);
595	        Rollup.Snapshot before = rollup.take(sheetId);
596	        for (Claim claim : theirs) {
597	            claim.setStated(false, null);
598	        }
599	        claims.saveAllAndFlush(theirs);
600	        statements.delete(last);
601	        statements.flush();
602	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
603	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
604	        rollup.recordChanges(sheetId, user, before);
605	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
606	    }
607	
608	    /** Refuse an edit of a claim whose editor another user has open. */
609	    private void refuseLocked(Claim claim, String user) {
610	        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
611	            throw new ClaimLockedException(claim.getLockedBy());
612	        }
613	    }
614	
615	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
616	     *  closed at the same moment is seen. */
617	    private void refuseClosed(String sheetId, LocalDate date) {
618	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
619	        if (periods.closedOn(sheetId, date)) {
620	            throw new PeriodClosedException();
621	        }
622	    }
623	
624	    /** Refuse voiding a SETTLED claim unless the user is a steward and the sheet's today is within 7 days
625	     *  of the date its status log last records it SETTLED. */
626	    private void refuseVoidSettled(Claim claim, String sheetId, String user) {
627	        if (!roles.isSteward(sheetId, user)) {
628	            throw new ClaimVoidException("Only a steward can void a settled claim.");
629	        }
630	        LocalDate settledOn = claim.getStatusLog().stream()
631	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
632	                .map(StatusChange::getOn)
633	                .reduce((first, last) -> last)
634	                .orElse(null);
635	        if (settledOn == null || sheets.today(sheetId).isAfter(settledOn.plusDays(7))) {
636	            throw new ClaimVoidException("A settled claim can only be voided within 7 days of settling it.");
637	        }
638	    }
639	
640	    /** Refuse settling or approving a claim with no proof whose due is above the proof threshold in force on
641	     *  its date; a due of n/a, or no threshold then, needs none. */
642	    private void refuseUnproved(Claim claim, BigDecimal due) {
643	        BigDecimal threshold = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new)
644	                .proofThresholdOn(claim.getDate());
645	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
646	            throw new ClaimProofException("The claim's due is above the proof threshold: add a proof first.");
647	        }
648	    }
649	
650	    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
651	     *  due of n/a, or a sheet with no limit, is within it. */
652	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
653	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
654	        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
655	    }
656	
657	    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
658	     *  0.00 or more that names one. */
659	    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
660	        if (amount.signum() >= 0) {
661	            if (corrects != null) {
662	                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
663	            }
664	            return;
665	        }
666	        if (corrects == null) {
667	            throw new ClaimCorrectionException(
668	                    "A negative amount is a correction: name the number of the settled claim it corrects.");
669	        }
670	        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
671	            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
672	        }
673	    }
674	
675	    /** Refuse a claim dated after its person's retirement date. */
676	    private static void refuseRetired(Person person, LocalDate date) {
677	        if (person.retiredOn(date)) {
678	            throw new PersonRetiredException();
679	        }
680	    }
681	
682	    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
683	     *  PENDING), else its live due; none when that is n/a. */
684	    private BigDecimal due(Claim claim, Person person) {
685	        if (claim.getSettledDue() != null) {
686	            return claim.getSettledDue();
687	        }
688	        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
689	    }
690	
691	    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
692	     *  screen shows it now. */
693	    private void logStatus(Claim claim, Person person, String user) {
694	        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
695	    }
696	
697	    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
698	     *  late charge on top; none when that is n/a. */
699	    private BigDecimal shownDue(Claim claim, Person person) {
700	        if (claim.getSettledDue() != null) {
701	            return claim.getSettledDue();
702	        }
703	        BigDecimal figure = due(claim, person);
704	        return figure == null ? null : charged(claim, figure);
705	    }
706	
707	    /** A claim's due from its figure: its late charge on the sheet's today on top while it is OPEN or
708	     *  PENDING, then at least the floor in force on its date (a correction has neither). */
709	    private BigDecimal charged(Claim claim, BigDecimal figure) {
710	        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
711	    }
712	
713	    /** The claim's rate figure: its amount at the rate in force on its date of its person's grade in force
714	     *  then, before any late charge or floor; none when no rate applies. */
715	    private BigDecimal liveDue(Claim claim, Person person) {
716	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
717	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
718	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
719	                .map(rate -> due(claim.getAmount(), rate, rounding))
720	                .orElse(null);
721	    }
722	
723	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
724	    private LocalDate roundingDate(Claim claim) {
725	        if (!claim.isCorrection()) {
726	            return claim.getDate();
727	        }
728	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
729	                .map(Claim::getDate).orElse(claim.getDate());
730	    }
731	
732	    /** An amount times a rate, divided by 100, rounded to cents. */
733	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
734	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);
735	    }
736	
737	    /** The due a settled claim was fixed at, as its audit line ends: n/a when it has none. */
738	    private static String dueField(Claim claim) {
739	        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
740	    }
741	
742	    /** A due as an audit line shows it: n/a when there is none. */
743	    private static String show(BigDecimal due) {
744	        return due == null ? "n/a" : due.toPlainString();
745	    }
746	
747	    /** Tell each user watching the claim's person, in the order they started watching. */
748	    private void notifyWatchers(Claim claim, Person person, String user) {
749	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
750	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUser()
751	                    + " person=" + person.getName() + " number=" + claim.getNumber());
752	        }
753	    }
754	
755	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
756	    private void audit(String event, Claim claim, Person person, String user) {
757	        audit(event, claim, person, user, claim.getNumber(), "");
758	    }
759	
760	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
761	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
762	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
763	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
764	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
765	    }
766	}
