  test("statement as of scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "cap", "2.00");
    await ui.setSetting(pg_uma, "grace-days", "0");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-10"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.hold(pg_uma, p_ada, {"from": "2026-03-05"})).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.35", "date": "2026-03-09"}));
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    expect(await ui.addProof(pg_uma, c_ben_0)).toBe(true);
    expect(await ui.addProof(pg_uma, c_ben_0)).toBe(true);
    expect(await ui.hold(pg_uma, p_ada, {"from": "2026-02-10"})).toBe(true);
    await ui.refresh(pg_uma);
    await ui.setSetting(pg_uma, "floor", "2.00");
    expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-09")).toBe(false);
    expect(await ui.pasteClaims(pg_uma, "Ben,20.00,,a, b\nBen,10.35,,\nAda,3.33,,")).toBe(3);
    const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
    const c_ben_2 = await ui.claimAt(pg_uma, p_ben, 2);
    const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
    expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "void")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
    await ui.refresh(pg_uma);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.reassign(pg_vic, c_ben_0, "Ada")).toBe(true);
    expect(await ui.editClaim(pg_vic, c_ben_1, {"date": "2026-03-01"})).toBe(true);
    const c_ada_2 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "99.95", "date": "2026-03-01"}));
    const c_ada_3 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "3.33"}));
    expect(await ui.retire(pg_vic, p_ben, "2026-02-25")).toBe(true);
    await ui.showRetired(pg_vic, true);
    const c_ada_4 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "4.00"}));
    expect(await ui.statement(pg_vic, p_ben)).toBe(true);
    await ui.refresh(pg_vic);
    await ui.refresh(pg_vic);
    expect(await ui.archive(pg_vic)).toBe(true);
    expect(await ui.addClaim(pg_vic, p_ben, {"amount": "4.00"})).toBeNull();
    await ui.refresh(pg_vic);
    await ui.expectAudit(sheet, [
    ]);
  });
  test("statement as of scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "terms-B", "20");
    await ui.setSetting(pg_uma, "grace-days", "3");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33"}));
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.claimAction(pg_wes, c_cam_0, "open")).toBe(true);
    expect(await ui.statementAsOf(pg_wes, p_cam, "2026-03-09")).toBe(false);
    const c_cam_1 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "1.00"}));
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_cam_0, "settle")).toBe(true);
    expect(await ui.statement(pg_vic, p_cam)).toBe(true);
    expect(await ui.claimAction(pg_vic, c_cam_1, "void")).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.editPerson(pg_vic, p_ada, {"grade": "C", "gradeFrom": "2026-04-02"}, {"grade": "B"})).toBe(true);
    const c_cam_2 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "10.35"}));
    expect(await ui.claimEditOpen(pg_vic, c_cam_2)).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.claimEditOpen(pg_wes, c_cam_2)).toBe(false);
    await ui.refresh(pg_vic);
    await ui.claimEditCancel(pg_vic, c_cam_2);
    expect(await ui.setRate(pg_vic, {"grade": "A", "pct": "12.50", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
    await ui.setToday(pg_vic, "2026-04-02");
    expect(await ui.addProof(pg_vic, c_cam_2)).toBe(true);
    expect(await ui.addProof(pg_vic, c_cam_2)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.addPatron(pg_vic, p_ada, "Cam")).toBe(true);
    expect(await ui.statement(pg_vic, p_ada)).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "25.00", "date": "2026-03-20"}));
    const c_cam_3 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "-1.00", "corrects": "1"}));
    expect(await ui.claimAction(pg_vic, c_cam_2, "void")).toBe(true);
    await ui.refresh(pg_vic);
    await ui.expectAudit(sheet, [
    ]);
  });
});

